<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_auth(); require_once __DIR__.'/../config/database.php'; $tracking=substr(trim((string)($_GET['tracking']??'')),0,15);$document=document_by_tracking($conn,$tracking);if(!$document){flash('error','Document not found.');redirect('dashboard.php');}$route=current_route($conn,$tracking);$historyStmt=$conn->prepare("SELECT l.*,CONCAT_WS(', ',s.lname,NULLIF(CONCAT(s.fname,' ',s.mname),'')) sender_name,CONCAT_WS(', ',r.lname,NULLIF(CONCAT(r.fname,' ',r.mname),'')) receiver_name FROM dr_logs l LEFT JOIN dr_users s ON s.id=l.sender LEFT JOIN dr_users r ON r.id=l.receiver WHERE l.id_track=? ORDER BY l.id ASC");$historyStmt->bind_param('s',$tracking);$historyStmt->execute();$history=$historyStmt->get_result()->fetch_all(MYSQLI_ASSOC);$currentUser=(int)$_SESSION['user_id'];$isHolder=$route&&(int)$route['receiver']===$currentUser;$page_title='Document details';$page_heading='Document '.$tracking;$active_page='';require __DIR__.'/../includes/app-shell.php'; ?>
<section class="panel"><div class="details"><div><dt>Tracking number</dt><dd><?= e($document['id_track']) ?></dd></div><div><dt>Current status</dt><dd><span class="badge <?= status_class($route['status']??$document['status']) ?>"><?= e($route['status']??$document['status']) ?></span></dd></div><div><dt>Title</dt><dd><?= e($document['title']) ?></dd></div><div><dt>Created</dt><dd><?= e($document['datecreated']) ?></dd></div><div class="field-full"><dt>Description</dt><dd><?= e($document['description']) ?></dd></div><div><dt>Author</dt><dd><?= e(user_name($document)) ?></dd></div><div><dt>Designation</dt><dd><?= e($document['designation']) ?></dd></div></div><?php if($isHolder && $document['status']==='open'): ?><div class="form-actions"><form method="post" action="<?= url('actions/receive-document.php') ?>"><?= csrf_input() ?><input type="hidden" name="tracking" value="<?= e($tracking) ?>"><?php if($route['status']==='Pending'): ?><button class="btn" type="submit">Receive document</button><?php endif; ?></form><?php if($route['status']==='Pending'): ?><a class="btn btn-danger" href="<?= url('documents/decline.php?tracking='.rawurlencode($tracking)) ?>">Decline</a><?php endif; ?><?php if($route['status']!=='Pending'): ?><a class="btn btn-secondary" href="<?= url('documents/forward.php?tracking='.rawurlencode($tracking)) ?>">Forward</a><a class="btn btn-danger" href="<?= url('documents/close.php?tracking='.rawurlencode($tracking)) ?>">Close document</a><?php endif; ?></div><?php endif; ?></section>
<section><div class="section-heading"><h2>Routing history</h2><a class="btn btn-secondary" href="<?= url('dashboard.php') ?>">Back</a></div><div class="panel"><ol class="timeline"><?php foreach($history as $event): ?><li><strong><?= e($event['status']) ?></strong><p><?= e($event['date']) ?> · <?= e(($event['sender_name']?:'Unknown').' → '.($event['receiver_name']?:'Unknown')) ?></p><?php if($event['remarks']): ?><p><?= e($event['remarks']) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
